const MSO = 'Medical Services Professional', CD = 'Clinical Director';
const latest = (rows, key) => [...rows].sort((a,b) => a[key].localeCompare(b[key])).at(-1);
const norm = text => (text || '').normalize('NFC').toLowerCase().trim();
